const months=['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'];let data,state={view:'overview',year:2026,period:'ytd',cutoff:8,unit:1000000,basis:'amount'},records={},plan={sales:0,variable:0,fixed:0};
const col=i=>{let s='';for(i++;i;i=Math.floor((i-1)/26))s=String.fromCharCode(65+(i-1)%26)+s;return s},num=(v,d=2)=>Number.isFinite(v)?v.toLocaleString('en-US',{minimumFractionDigits:d,maximumFractionDigits:d}):'—',money=v=>num(v===null?null:v/state.unit),pct=v=>Number.isFinite(v)?num(v,1)+'%':'—',ratio=(a,b)=>a!==null&&b!==null&&b!==0?a/b:null,sub=(a,b)=>a!==null&&b!==null?a-b:null;
