function normalize(){records={};for(const [kind,book]of Object.entries(data)){const c=book.cells,start=kind==='income'?2:3;let lastDate;records[kind]=[];for(let j=start;j<150;j++){const date=c[col(j)+'3'];if(typeof date==='number')lastDate=new Date(Math.round((date-25569)*86400000));if(!lastDate)continue;const type=c[col(j)+'4'];if(!['Budget','Actual'].includes(type))continue;for(let r=5;r<=300;r++){const label=c[(kind==='income'?'B':'C')+r];if(!label)continue;const raw=c[col(j)+r];records[kind].push({r,label:String(label).trim(),group:c['A'+r]||'',sub:c['B'+r]||'',year:lastDate.getUTCFullYear(),month:lastDate.getUTCMonth(),type,value:typeof raw==='number'&&Number.isFinite(raw)?raw:null,cell:col(j)+r});}}}}
function ids(){return state.period==='ytd'?Array.from({length:state.cutoff+1},(_,i)=>i):[+state.period]}
