function rowTable(rows,kind='income',per=false){return table(['Line item',`Actual (${per?'BDT / sales MT':unit()})`,'Budget','Actual − budget','Variance %'],rows.map(r=>{let a=val(r,'Actual',kind),b=val(r,'Budget',kind);if(per){a=ratio(a,val(19));b=ratio(b,val(19,'Budget'));}const physical=kind==='income'&&records.income.find(x=>x.r===r)?.physical;const fmt=per||physical?num:money,d=sub(a,b),p=ratio(d,b===null?null:Math.abs(b));return [`<button data-row="${r}" data-kind="${kind}">${esc(label(r,kind))}${physical?' (MT)':''}</button>`,fmt(a),fmt(b),fmt(d),pct(p===null?null:p*100)];}));}
