function insights(){const out=[],sales=val(31),b=val(31,'Budget'),profit=val(67),pb=val(67,'Budget'),gm=ratio(val(46),sales),util=ratio(val(12),val(5));if(sales!==null&&b!==null&&b!==0)out.push(['Sales against plan',`Net sales are ${pct(sales/b*100)} of budget, a ${money(Math.abs(sales-b))} ${unit()} ${sales<b?'shortfall':'surplus'}.`,31]);if(profit!==null)out.push([profit<0?'Loss position':'Profit position',`Net ${profit<0?'loss':'profit'} is ${money(Math.abs(profit))} ${unit()}${pb!==null?`, versus a budget of ${money(pb)} ${unit()}`:''}.`,67]);if(gm!==null)out.push(['Gross margin',`Gross profit represents ${pct(gm*100)} of net sales after commission.`,46]);if(util!==null)out.push(['Capacity utilization',`Production is ${pct(util*100)} of reported capacity.`,12]);const gaps=[33,34,35,36,37,38,39,40,43,44,45,48,50,62].map(r=>({r,d:sub(val(r),val(r,'Budget'))})).filter(x=>x.d!==null&&x.d>0).sort((a,b)=>b.d-a.d);if(gaps.length)out.push(['Largest comparable cost overrun',`${label(gaps[0].r)} exceeds budget by ${money(gaps[0].d)} ${unit()}. Review the supporting ledger before assigning a cause.`,gaps[0].r]);return out.length?out.map((o,i)=>`<div class="insight"><b class="n">0${i+1}</b><div><h3>${o[0]}</h3><p>${o[1]}</p><button class="action source" data-row="${o[2]}">Source & calculation inputs</button></div></div>`).join(''):empty('Insufficient comparable data');}
