function breakdown(){const groups=[...new Set(records.detail.map(x=>x.group))];return panel('Expense groups & ledger detail','Groups follow the supplied ledger labels. They are not assigned departmental ownership.',`<input id="search" class="search" placeholder="Search general ledger, sub-ledger or particulars" aria-label="Search ledger">${table(['General ledger','Sub-ledger','Particulars',`Actual (${unit()})`],records.detail.filter(x=>x.year==state.year&&x.month===0&&x.type==='Actual').map(x=>[esc(x.group),esc(x.sub),`<button data-kind="detail" data-row="${x.r}">${esc(x.label)}</button>`,money(val(x.r,'Actual','detail'))]))}`);}
function products(){return panel('Product sales & production','Product-specific cost and margin allocations are unavailable. Revenue below is gross sales, before VAT.',table(['Product',`Gross sales (${unit()})`,'Sales MT','Production MT','Gross sales / MT','Product margin'],[['GI Fittings',20,13,6],['Manhole Cover',21,14,7],['Boiler Parts',22,15,8],['BD Auto Rickshaw',23,null,null],['Rail Way Insert',24,18,11],['Gas stove Accessories',25,17,10]].map(([n,s,v,p])=>[n,money(val(s)),num(val(v),2),num(val(p),2),num(ratio(val(s),val(v)),0),'—'])))+panel('Product cost & profitability','Awaiting product-level cost allocation.',empty());}
function breakEven(){const revenue=val(31),variable=val(32),fixed=val(42),opex=val(47),cm=ratio(sub(revenue,variable),revenue),burden=fixed!==null&&opex!==null?fixed+opex:null,be=cm!==null&&cm>0&&burden!==null?burden/cm:null;return panel('Operating break-even','Derived from reported variable COGS, fixed overhead and operating expenses. Excludes finance costs, tax and other income/expenses.',`<div class="cards">${card('Contribution ratio',pct(cm===null?null:cm*100),'(Net sales − variable COGS) / net sales')}${card('Operating break-even sales',money(be),unit())}${card('Margin of safety',money(sub(revenue,be)),unit())}</div>${rowTable([31,32,41,42,47])}`);}
