function notes(){const map=[[29,18],[33,37],[48,87],[50,106],[61,114]];return `<div class="grid">${panel('Data sources','Only the two supplied workbook types feed this dashboard.',table(['Source','Worksheet','Numeric cells'],Object.values(data).map(b=>[esc(b.name),esc(b.sheet),Object.values(b.cells).filter(x=>typeof x==='number').length]))+`<p class="source">Upload replaces the matching workbook, not appends to it. Files must retain the same row labels and paired monthly Budget / Actual layout. Save formulas in Excel before uploading so cached results are available.</p><button class="action" id="reset">Restore attached data</button>`,true)}${panel('Source reconciliation',`${period()} · Actuals · ${unit()}. Differences are shown, never silently adjusted.`,table(['Statement line','Statement','Break-up','Difference'],map.map(([i,d])=>[esc(label(i)),money(val(i)),money(val(d,'Actual','detail')),money(sub(val(i),val(d,'Actual','detail')))])),true)}${panel('Reporting rules','How the figures are treated',`<p>2024–2025 values remain Budget as labelled in the source. Actuals are blank. No historical relabelling is applied.</p><p>YTD requires every selected month to contain a numeric value for each line. A partially missing line stays blank. Genuine zero values remain zero.</p><p>January–September 2026 is the initial reporting range. October–December columns are retained but currently blank.</p><p>All ratios are calculated from aggregate amounts. No financial statement subtotal is summed with its components.</p><p>Refresh reloads the saved browser dataset and recalculates every view. It does not access a file on your computer automatically. Upload revised workbooks to update figures.</p><p>Uploads are stored in this browser only. The original attached data is available to the private site's owner.</p>`,true)}</div>`;}
